const express = require('express');
const { createRemoteJWKSet, jwtVerify } = require('jose');
const db = require('../db');

const app = express();
app.use(express.json());

app.post('/api/webhooks/partner-event', async (req, res) => {
  const token = req.headers['x-partner-signature'];
  const partnerId = req.headers['x-partner-id'];
  if (!token || !partnerId) {
    return res.status(401).json({ error: 'Missing partner credentials' });
  }

  // Fetch verified, pinned partner JWKS URL from database
  const partner = await db('registered_partners').where({ id: partnerId }).first();
  if (!partner || !partner.jwks_url) {
    return res.status(403).json({ error: 'Unrecognized partner' });
  }

  try {
    const jwks = createRemoteJWKSet(new URL(partner.jwks_url));
    const { payload } = await jwtVerify(token, jwks, {
      algorithms: ['RS256'],
      subject: partnerId
    });

    const { targetMerchantId, eventData } = req.body;
    // Verify partner is linked to target merchant
    const link = await db('merchant_partners').where({ merchant_id: targetMerchantId, partner_id: partnerId }).first();
    if (!link) {
      return res.status(403).json({ error: 'Partner not linked to target merchant' });
    }

    await db('merchant_events').insert({
      merchant_id: targetMerchantId,
      partner_id: payload.sub,
      payload: eventData
    });

    return res.json({ status: 'Event recorded' });
  } catch (err) {
    return res.status(400).json({ error: 'Signature verification failed' });
  }
});

module.exports = app;
